-- TRIPSPHERE reference data — destinations
INSERT OR IGNORE INTO destinations
(id, slug, name, state, region, tagline, summary, description, image, lat, lng, best_season, ideal_days, avg_daily_budget, interests, is_hidden, popularity, unesco) VALUES
(1,'hampi','Hampi','Karnataka','South','Boulders, temples and a lost empire',
 'A UNESCO World Heritage landscape of granite boulders, ancient bazaars and 14th-century temples beside the Tungabhadra river.',
 'Hampi was the capital of the Vijayanagara empire and remains one of the most cinematic archaeological sites in Asia. Cycle between temple complexes at dawn, climb Matanga Hill for sunset, and cross the river to Anegundi for a slower, greener side of the valley.',
 '/images/hampi.jpg',15.3350,76.4600,'October to February',3,2200,'["heritage","history","photography","adventure"]',0,88,1),
(2,'mysore','Mysore','Karnataka','South','Palaces, silk and sandalwood mornings',
 'A royal city of illuminated palaces, flower markets and the aromatic buzz of Devaraja Market.',
 'Mysore wears its royal history lightly. The Amba Vilas Palace sets the tone, but the real city lives in its markets, its silk shops and the climb up Chamundi Hill. Plan a slow morning at the market and keep an evening free for the palace illumination.',
 '/images/jaipur.jpg',12.2958,76.6394,'October to March',2,2600,'["heritage","culture","food","family"]',0,82,0),
(3,'coorg','Coorg','Karnataka','South','Coffee country in the Western Ghats',
 'Misty plantation hills, waterfalls and homestays where the air smells of cardamom and roasted coffee.',
 'Coorg, or Kodagu, is a highland district of coffee estates, orange orchards and forested ridges. Days here are built around estate walks, waterfall stops and long lunches. It is the easiest place in Karnataka to slow down.',
 '/images/coorg.jpg',12.3375,75.8069,'September to March',3,3200,'["nature","adventure","food","photography"]',0,79,0),
(4,'chikmagalur','Chikmagalur','Karnataka','South','Peaks, tea and hidden waterfalls',
 'The birthplace of Indian coffee, with ridge-top temples, tea estates and waterfall trails.',
 'Chikmagalur rewards travellers who leave the main road. Mullayanagiri is the state high point, Hebbe Falls hides inside a coffee estate, and the surrounding hills hold small temples with almost no crowds.',
 '/images/munnar.jpg',13.3161,75.7720,'September to February',2,2800,'["nature","adventure","photography"]',1,61,0),
(5,'gokarna','Gokarna','Karnataka','South','Temple town with a barefoot coastline',
 'A pilgrimage town that quietly doubles as one of India''s most relaxed beach escapes.',
 'Gokarna balances ancient temple ritual with cliff-path beaches. Walk from Kudle to Om Beach, continue to Paradise Beach if the tide allows, and return for the evening aarti. It is an easy, inexpensive coastal reset.',
 '/images/goa.jpg',14.5479,74.3188,'November to February',2,2000,'["beach","relaxation","nature"]',1,64,0),
(6,'kabini','Kabini','Karnataka','South','Safari country on the edge of Nagarhole',
 'Riverine forest, elephant corridors and some of the best wildlife sightings in southern India.',
 'Kabini sits between Nagarhole National Park and the Kabini reservoir. Safari drives at dawn and dusk are the main event, with boat safaris and riverside sundowners filling the hours between.',
 '/images/wildlife.jpg',11.9167,76.1833,'October to May',2,4500,'["wildlife","nature","photography"]',1,58,0),
(7,'munnar','Munnar','Kerala','South','Tea terraces above the clouds',
 'Endless tea gardens, cool air and winding hill roads through the highest ranges of Kerala.',
 'Munnar is a hill station built around tea. Walk the estates, watch the mist move through the valleys, and take the ridge road to Top Station for the best view in the region. Evenings are for cardamom tea and warm conversation.',
 '/images/munnar.jpg',10.0889,77.0595,'September to March',3,3000,'["nature","relaxation","photography"]',0,80,0),
(8,'alleppey','Alleppey','Kerala','South','The backwater capital',
 'A slow lattice of canals, paddy fields and houseboats drifting through Kerala''s waterways.',
 'Alleppey is the entry point to the Kuttanad backwaters. A day cruise or an overnight houseboat gives you the full rhythm: village landings, toddy shops and sunset over open paddy. Kayaks reach narrow canals that houseboats cannot.',
 '/images/kerala.jpg',9.4981,76.3388,'September to March',2,3500,'["nature","relaxation","food"]',0,84,0),
(9,'goa','Goa','Goa','West','Beaches, Portuguese lanes and long lunches',
 'India''s most famous coastline, with a Latin quarter, spice farms and a serious food culture.',
 'Goa is many places at once. The north is lively and social, the south is quiet and spread out, and Panaji holds a compact Portuguese-era quarter worth a full day. Go beyond the beach and you find forts, spice farms and river cruises.',
 '/images/goa.jpg',15.2993,74.1240,'November to March',4,3800,'["beach","food","nightlife","relaxation"]',0,92,0),
(10,'jaipur','Jaipur','Rajasthan','North','The pink city, in full colour',
 'Fortified hills, bazaars of block print and a walled city painted in rose.',
 'Jaipur is the most accessible entry to Rajasthan: Amber Fort in the morning, the old city bazaars in the afternoon, and a rooftop dinner inside the walls. The walled city is a UNESCO World Heritage site for its planned grid and architecture.',
 '/images/jaipur.jpg',26.9124,75.7873,'October to March',3,3300,'["heritage","culture","food","photography"]',0,94,1),
(11,'udaipur','Udaipur','Rajasthan','North','Lakes, palaces and evening light',
 'A city of white palaces around a still lake, best seen from a boat at sunset.',
 'Udaipur is Rajasthan at its most romantic. The City Palace complex overlooks Lake Pichola, and the ghats below come alive at dusk. Leave time for the smaller havelis and the Monsoon Palace viewpoint.',
 '/images/jaipur.jpg',24.5854,73.7125,'September to March',3,3900,'["heritage","relaxation","photography"]',0,86,0),
(12,'jaisalmer','Jaisalmer','Rajasthan','North','The golden fort in the desert',
 'A living sandstone fort rising from the Thar, with camel country all around.',
 'Jaisalmer Fort is one of the few living forts in the world, with families and shops inside its walls. Beyond the city, the Sam dunes and the abandoned village of Kuldhara make for a full desert day.',
 '/images/jaipur.jpg',26.9157,70.9083,'October to February',2,3100,'["heritage","adventure","photography"]',1,66,1),
(13,'varanasi','Varanasi','Uttar Pradesh','North','The oldest living city on the Ganga',
 'Ghats, aarti and narrow lanes that hold centuries of ritual and craft.',
 'Varanasi is best understood slowly: a sunrise boat along the ghats, an afternoon in the lanes, and the evening aarti at Dashashwamedh. Sarnath, twenty minutes away, adds the Buddhist chapter of the story.',
 '/images/kerala.jpg',25.3176,82.9739,'October to March',2,2200,'["heritage","culture","religion"]',0,90,0),
(14,'rishikesh','Rishikesh','Uttarakhand','North','River, ashrams and adventure',
 'Where the Ganga leaves the mountains: rafting, yoga and quiet river beaches.',
 'Rishikesh splits neatly between adventure and stillness. Mornings are for rafting or a walk to the suspension bridges; afternoons are for ashrams, cafes and the evening Ganga aarti at Triveni Ghat.',
 '/images/ladakh.jpg',30.0869,78.2676,'September to November, February to May',3,2400,'["adventure","nature","religion"]',0,78,0),
(15,'ladakh','Ladakh','Ladakh','North','High passes and impossible blue',
 'A high-altitude desert of monasteries, prayer flags and lakes that change colour by the hour.',
 'Ladakh needs time and acclimatisation. Leh is the base; from there the monasteries of the Indus valley, the dunes of Nubra and the long drive to Pangong Tso each deserve a day. Altitude, not distance, sets the pace.',
 '/images/ladakh.jpg',34.1526,77.5771,'June to September',5,5200,'["adventure","nature","photography"]',0,89,0),
(16,'manali','Manali','Himachal Pradesh','North','Pine valleys and mountain roads',
 'A base for snow, hot springs and the long road toward Lahaul and Spiti.',
 'Manali works at every pace: a day in Solang Valley, an afternoon at Hadimba Temple, and slow evenings in Old Manali. Beyond the town, the Atal Tunnel opens the high desert of Lahaul.',
 '/images/ladakh.jpg',32.2396,77.1887,'March to June, September to November',4,3000,'["adventure","nature"]',0,83,0),
(17,'darjeeling','Darjeeling','West Bengal','East','Tea, toy trains and sunrise ridges',
 'Cool hill air, colonial-era charm and the world''s most famous tea gardens.',
 'Darjeeling is a morning place: Tiger Hill at sunrise, then a tea estate tour, then the mall road and a slow lunch. The narrow-gauge railway is a UNESCO-listed engineering curiosity.',
 '/images/munnar.jpg',27.0410,88.2663,'March to May, October to December',3,2700,'["nature","food","heritage"]',0,75,0),
(18,'pondicherry','Pondicherry','Puducherry','South','French quarter, sea breeze and coffee',
 'A coastal town of mustard-yellow villas, bakeries and a quiet promenade.',
 'Pondicherry mixes Tamil and French heritage in a way that feels effortless. Rent a cycle for White Town, visit Auroville in the afternoon, and keep an evening for the promenade and a long dinner.',
 '/images/goa.jpg',11.9416,79.8083,'October to February',2,2600,'["beach","food","culture","relaxation"]',0,72,0),
(19,'mahabalipuram','Mahabalipuram','Tamil Nadu','South','Stone temples by the sea',
 'Seventh-century rock-cut temples and shore shrines in a quiet coastal town.',
 'Mahabalipuram is compact enough for a day and rich enough for two. The Shore Temple faces the Bay of Bengal, the Pancha Rathas sit in the sand, and the town remains a working centre of stone carving.',
 '/images/hampi.jpg',12.6208,80.1944,'November to February',1,2100,'["heritage","beach"]',1,63,1),
(20,'shillong','Shillong','Meghalaya','East','Scotland of the east',
 'Pine ridges, waterfalls and the gateway to Meghalaya''s living root bridges.',
 'Shillong is a good base for the wettest, greenest corners of India. Use it for Elephant Falls and Umiam Lake, then go further for Mawphlang''s sacred grove and the canyons at Laitlum.',
 '/images/coorg.jpg',25.5788,91.8933,'September to May',3,3200,'["nature","adventure","photography"]',1,57,0),
(21,'havelock','Havelock Island','Andaman and Nicobar Islands','Islands','Turquoise water, white sand, no rush',
 'Quiet island beaches with coral reefs, jungle trails and the best sunsets in the country.',
 'Havelock, now officially Swaraj Dweep, is the Andamans at their simplest: beach, reef, jungle, repeat. Radhanagar is the famous one, but Elephant Beach and the smaller coves reward an early start.',
 '/images/goa.jpg',12.0167,92.9833,'October to May',4,4800,'["beach","relaxation","adventure"]',1,70,0);
